head.script:
// 테스트 설명, 유효성 값 설정
//  - _2 담당 : GridView 의 mergeCells="bycolupper" 방식 (동작 전제 중 bycolupper 부분 + 왼쪽/오른쪽 위치 Column)
//  - colMerge 방식 · ID 설정 · 여러 Column · 위 Row 와 다른 경우는 _1, colMerge 방식의 upperColumn 연쇄는 _3 담당
scwin.tData = {
    "description" : "[column > P > upperColumn]<br/>Column 에서 연속된 Row 의 값이 같아 하나의 Cell 처럼 표시할때 함께 기준값으로 처리할 상위 Column 을 설정합니다.",
    "validation" : [
        "Column 의 colMerge='true' 이거나 GridView 의 mergeCells='bycolupper' 인 경우에 동작합니다.",
        "GridView 의 mergeCells='bycolupper' 일때 upperColumn 속성에 설정한 Column 의 값이 위 Row 와 다르면 하나의 Cell 처럼 표시되지 않습니다.",
        "GridView 의 mergeCells='bycolupper' 일때, upperColumn 속성에는 왼쪽 위치의 Column 만 설정할 수 있으며 오른쪽 위치의 Column 을 설정하면 upperColumn 속성을 설정하지 않은 것과 같이 'bycol' 방식으로 병합됩니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (mergeCells=bycolupper, 담당자 upperColumn=team)
    con_mergeCells.setSelectedIndex(2);
    con_upperColumn.setSelectedIndex(1);

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 행 데이터 (12건) : 사업부 -> 팀 -> 담당자 계층 + 담당자 오른쪽에 등급 Column
//  - Row 2 -> 3  : 담당자 이서연 같음 / 팀 다름(영업1팀 -> 영업2팀) / 사업부 같음
//  - Row 4 -> 5  : 담당자 박지훈 같음 / 팀 같음(영업2팀)            / 사업부 다름(가전 -> 모바일) / 등급 다름(B -> A)
//  - Row 8 -> 9  : 담당자 최유나 같음 / 팀 다름(영업3팀 -> 영업1팀) / 사업부 같음              / 등급 다름(B -> A)
scwin.rowPattern = [
    { "division" : "가전", "team" : "영업1팀", "manager" : "김민수", "grade" : "A", "amount" : "1200" },
    { "division" : "가전", "team" : "영업1팀", "manager" : "김민수", "grade" : "A", "amount" : "800" },
    { "division" : "가전", "team" : "영업1팀", "manager" : "이서연", "grade" : "B", "amount" : "950" },
    { "division" : "가전", "team" : "영업2팀", "manager" : "이서연", "grade" : "B", "amount" : "600" },
    { "division" : "가전", "team" : "영업2팀", "manager" : "박지훈", "grade" : "B", "amount" : "700" },
    { "division" : "모바일", "team" : "영업2팀", "manager" : "박지훈", "grade" : "A", "amount" : "1100" },
    { "division" : "모바일", "team" : "영업2팀", "manager" : "박지훈", "grade" : "A", "amount" : "450" },
    { "division" : "모바일", "team" : "영업3팀", "manager" : "최유나", "grade" : "B", "amount" : "880" },
    { "division" : "모바일", "team" : "영업3팀", "manager" : "최유나", "grade" : "B", "amount" : "520" },
    { "division" : "모바일", "team" : "영업1팀", "manager" : "최유나", "grade" : "A", "amount" : "300" },
    { "division" : "모바일", "team" : "영업1팀", "manager" : "정하늘", "grade" : "A", "amount" : "640" },
    { "division" : "모바일", "team" : "영업1팀", "manager" : "정하늘", "grade" : "A", "amount" : "770" }
];



// comp 생성
//  - GridView mergeCells = con_mergeCells (미설정 / bycol / bycolupper)
//  - manager : 검증 대상 Body Column (upperColumn = con_upperColumn, team / division 은 왼쪽 위치, grade 는 오른쪽 위치)
//  - defaultCellHeight 24 / 높이 330px : 12 Row 가 모두 그려지게 한다 (세로 가상 렌더링으로 화면 밖 Row 는 td 가 없어 병합 범위를 측정할 수 없음)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정 (미설정 옵션은 속성 자체를 넣지 않는다)
    let cMergeCells = con_mergeCells.getValue();
    let cUpperColumn = con_upperColumn.getValue();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] upperColumn 은 담당자 Column 에만 적용 (team / division = 담당자 왼쪽 위치, grade = 담당자 오른쪽 위치)\n[확인] (병합 상태 확인) 버튼으로 Column 별로 하나의 Cell 로 병합된 Row 범위 확인 (담당자 값이 이어지는 Row 2-3 / Row 4-5 / Row 8-9 의 분리 여부)"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 dataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="division" name="사업부" dataType="text"></w2:column>';
    strDlt += '<w2:column id="team" name="팀" dataType="text"></w2:column>';
    strDlt += '<w2:column id="manager" name="담당자" dataType="text"></w2:column>';
    strDlt += '<w2:column id="grade" name="등급" dataType="text"></w2:column>';
    strDlt += '<w2:column id="amount" name="실적" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON(scwin.rowPattern, false);

    // GridView / 검증 대상 Column 속성
    let properties = {
        dataList : "data:dlt_bind",
        mergeCells : cMergeCells
    };
    let cList = $c.gcm.createCList(properties);
    let attrUpper = (cUpperColumn === '') ? '' : ' upperColumn="' + cUpperColumn + '"';

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" defaultCellHeight="24" style="width:540px;height:330px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="사업부"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column2" value="팀"></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="column3" value="담당자"></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="column4" value="등급"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column5" value="실적"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="division" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="team" value=""></w2:column>';
    strTarget += '<w2:column width="110" style="" inputType="text" id="manager" value=""' + attrUpper + '></w2:column>';
    strTarget += '<w2:column width="80" style="" inputType="text" id="grade" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="amount" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// validation 1 ~ 3 판정 출력 : Column 별로 하나의 Cell 로 병합된 Row 범위
//  - 화면에 표시된 Body Cell(td) 의 시작 Row 와 rowSpan 으로 범위를 구한다 (병합되어 숨겨진 td 는 제외)
//  - 출력 : Column명 : 값(Row a~b) / 값(Row c) ...
scwin.btn_checkMerge_onclick = function () {
    let arrCol = [ { id : "division", name : "사업부" }, { id : "team", name : "팀" }, { id : "manager", name : "담당자" }, { id : "grade", name : "등급" } ];
    let dataLength = target1.getDataLength();
    for (let c = 0; c < arrCol.length; c++) {
        let colIndex = target1.getColumnIndex(arrCol[c].id);
        let groups = [];
        let covered = 0;
        for (let r = 0; r < dataLength; r++) {
            let td = document.querySelector("#" + target1.id + "_cell_" + r + "_" + colIndex);
            if (!td || getComputedStyle(td).display === "none") {
                continue;
            }
            let rs = td.rowSpan || 1;
            groups.push(td.textContent + "(Row " + r + (rs > 1 ? "~" + (r + rs - 1) : "") + ")");
            covered += rs;
        }
        let text = arrCol[c].name + " : " + groups.join(" / ");
        if (covered !== dataLength) {
            text += " / 측정된 Row " + covered + "개 (전체 " + dataLength + "개)";
        }
        wf_body_bottom.getObj("scwin").setReturnValue(text);
    }
}
